def hasValidPath(grid: list[list[int]]) -> bool:
    R, C = len(grid), len(grid[0])
    # Dirs: 0=up, 1=down, 2=left, 3=right
    pipe = {
        1: {2: (0, -1, 3), 3: (0, 1, 2)},
        2: {0: (-1, 0, 1), 1: (1, 0, 0)},
        3: {2: (0, -1, 3), 1: (1, 0, 0)},
        4: {3: (0, 1, 2), 1: (1, 0, 0)},
        5: {2: (0, -1, 3), 0: (-1, 0, 1)},
        6: {3: (0, 1, 2), 0: (-1, 0, 1)}
    }
    visited = [[False] * C for _ in range(R)]
    from collections import deque
    q = deque([(0, 0)])
    visited[0][0] = True
    while q:
        r, c = q.popleft()
        if r == R - 1 and c == C - 1: return True
        for dir_out, (dr, dc, req_in) in pipe[grid[r][c]].items():
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc]:
                if req_in in pipe[grid[nr][nc]]:
                    visited[nr][nc] = True
                    q.append((nr, nc))
    return False

